using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// A source-generated context that only knows about "Person"
[JsonSerializable(typeof(Person))]
partial class MyContext : JsonSerializerContext;

record Person(string Name, int Age);

// --- setup ---
var options = new JsonSerializerOptions
{
    TypeInfoResolver = MyContext.Default
};

// 1) GetTypeInfo<T>() — strongly-typed metadata (returns JsonTypeInfo<T>)
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Type : {personInfo.Type.Name}");
Console.WriteLine($"Round-trip: {JsonSerializer.Serialize(new Person("Alice", 30), personInfo)}");

// 2) TryGetTypeInfo — probe without throwing
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"Person metadata found  (kind: {found!.Kind})");
else
    Console.WriteLine("Person metadata NOT found");

// DateTime is NOT in the context, so this returns false instead of throwing
if (options.TryGetTypeInfo(typeof(DateTime), out _))
    Console.WriteLine("DateTime metadata found");
else
    Console.WriteLine("DateTime metadata NOT found (no exception thrown)");

